  "range_high": 0.03,
  "summary": [
    "Credible polls show CDU/Greens ahead of AfD in Baden-Württemberg; AfD around 19-21% and unlikely to lead BW.",
    "Forecasts and prediction markets typically do not place AfD as the largest party in BW.",
    "BW historical base-rate supports a low anchor for AfD leading.",
    "An outlier (Oct 2025 BWTrend) briefly suggested AfD ahead, but broader data do not confirm that shift."
  ],
  "confidence": "low",
  "narrative": "Base-rate BW history and current polls strongly weigh against AfD leading; a single outlier and variable late-campaign dynamics provide limited upside, yielding a very low posterior probability of 1%.",
  "justification": {
    "anchor": {
      "probability": 0.05,
      "basis": "Base-rate reference class: Baden-Württemberg state elections; historically CDU/Greens have led; AfD has never led BW; anchor probability reflects the longstanding base-rate."
    },
    "factor_updates": [
      {
        "factor": "Polls show CDU ahead with Greens close, AfD far behind",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Contemporary polls place CDU high 20s–30%, Greens mid-20s, AfD around 19–21%; this makes AfD unlikely to be the largest party."
      },
      {
        "factor": "AfD vote share trailing behind CDU/Greens in most polls",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": " Consistent polling placing AfD behind the two main blocs reduces the probability of leading in seats."
      },
      {
        "factor": "Outlier BWTrend poll suggested AfD could overtake Greens",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "An outlier indicating potential lead could lift probability, but evidence did not persist across subsequent polls."
      },
      {
        "factor": "Prediction markets rank AfD behind CDU and Greens",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Market forecasts generally do not project AfD as the largest party in BW."
      },
      {
        "factor": "Historical base-rate: AfD has never led BW in state elections",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Long-run BW history anchors expectations toward CDU/Greens rather than AfD leading."
      }
    ],
    "synthesis_rationale": "The posterior probability was calibrated by weighting the majority of credible, non-outlier signals toward CDU/Greens leading and by applying the BW base-rate. The lone outlier and potential late-turnout effects provide only weak upside; correlated factors reinforce a very low final probability, yielding a 1% posterior with a narrow practical uncertainty band."
  }
}

